function purgeDialog(id){const e=db.exams.find(e=>e.id===id&&e.deletedAt);if(!e)throw Error('Prüfung ist nicht im Papierkorb.');openModal('Prüfung endgültig löschen?',`<p><strong>${E(e.title)}</strong></p><p>Dieser Prüfungsentwurf mit seinen Bearbeitungen wird endgültig aus dem aktuellen Datenbestand entfernt und kann im Tool nicht wiederhergestellt werden.</p><p>Die Aufgabenbank, Originalunterlagen und andere Prüfungen bleiben erhalten. Bereits heruntergeladene Kopien und frühere Sicherungen werden dadurch nicht gelöscht.</p>`,btn('show-trash','Abbrechen')+btn('confirm-purge-exam','Endgültig löschen','danger',id));}
async function purgeExam(id){const app=$('#app'),dialog=$('#dialog'),cancel=ev=>ev.preventDefault();app.inert=true;dialog.inert=true;dialog.addEventListener('cancel',cancel);try{if(online)await flush();else clearTimeout(saveTimer);const next=C.clone(db);C.purgeExam(next,id);if(online)await online.save(next);else if(storage)await new Promise((resolve,reject)=>{const t=storage.transaction('projects','readwrite');t.objectStore('projects').put(next,storageKey);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error);});db=next;dirty=!online&&!storage;saveError=null;storageText=online?'Zentral gespeichert':storage?'Lokal gespeichert · Backup empfohlen':'Nur Arbeitsspeicher · Datei sichern';if(examId===id)examId=null;render();trashView();toast('Prüfung endgültig gelöscht.');}catch(e){if(e.status===409){saveError=e;storageText='Speicherkonflikt · Zentralen Stand neu laden';render();}throw e;}finally{app.inert=false;dialog.inert=false;dialog.removeEventListener?.('cancel',cancel);}}
